  return { ok: true, status: 201, reused: false, import: await viewOf(deps, row!) };
}

/** Current state of one import (syncs the service record and settles the revision status once). */
export async function getImport(deps: ImporterDeps, userId: string, projectId: string): Promise<ImportView | null> {
  const row = await deps.getImportRow(userId, projectId);
  return row ? viewOf(deps, row) : null;
}

export async function listImports(deps: ImporterDeps, userId: string): Promise<ImportView[]> {
  const rows = await deps.listImportRows(userId);
  return Promise.all(rows.slice(0, 100).map((r) => viewOf(deps, r, { sync: false })));
}

/** Removes the quarantined upload. The project and its append-only history (hashes + attestation) stay. */
export async function deleteImport(deps: ImporterDeps, userId: string, projectId: string): Promise<{ ok: boolean; status: number }> {
  const row = await deps.getImportRow(userId, projectId);
  if (!row) return { ok: false, status: 404 };
  await deps.quarantine.delete(row.meta.importId);
  return { ok: true, status: 200 };
}

/** Run the conflict engine + inventory for an imported PLUGIN against one of the user's servers (read-only). */
export async function checkImportConflicts(deps: ImporterDeps, userId: string, projectId: string, serverId: string): Promise<{ ok: true; report: ConflictReport } | { ok: false; status: number; error: string }> {
  const row = await deps.getImportRow(userId, projectId);
  if (!row) return { ok: false, status: 404, error: "Not found" };
  if (row.meta.kind !== "source" && row.meta.kind !== "jar") return { ok: false, status: 400, error: "Conflict checks against a server cover plugin imports for now." };
  if (!deps.openServerReadOnly) return { ok: false, status: 503, error: "Server checks are not available right now." };
  let bytes: Buffer | null = null;
  if (row.meta.kind === "jar") bytes = await deps.quarantine.get(row.meta.importId);
  else if (row.meta.modBuildId && deps.fetchArtifact) bytes = await deps.fetchArtifact(row.meta.modBuildId);
  if (!bytes) return { ok: false, status: 409, error: row.meta.kind === "jar" ? "The uploaded jar was deleted; import it again to check it." : "Wait until the import has built, then check it." };
  const view = await deps.openServerReadOnly(userId, serverId);
  if (!view) return { ok: false, status: 404, error: "Server not found" };
  try {
    const inv = await scanServer(view.fs, { base: view.base });
    const name = SAFE_NAME(row.meta.filename.endsWith(".jar") ? row.meta.filename : `${row.title ?? "imported"}.jar`);
    // the same plugin already on the server (an older copy of this import) is the one being replaced, not a clash
    const cand = candidateJar(name, bytes, { id: `import:${row.projectId}` });
    const ownName = cand.plugin?.descriptor?.name?.toLowerCase();
    const filtered = { ...inv, plugins: inv.plugins.filter((p) => !ownName || p.descriptor?.name?.toLowerCase() !== ownName) };
    return { ok: true, report: checkAgainstServer(filtered, [cand]) };
  } finally {
    view.close?.();
  }
}

