// Cyrus import: QUARANTINE storage for uploads (the injectable store). The raw upload is written here FIRST, before any
// parsing, and only ever read back as bytes (re-ingest, conflict checks): never extracted to disk, never executed, never
// served. Files are 0600 in a 0700 directory, named by the opaque import id. deleteImport removes the bytes.
// Server only (node:fs). Tests use MemoryQuarantine.
import { mkdir, readFile, rename, rm, stat, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { cyrusConfig } from "../config";

export interface QuarantineStore {
  put(importId: string, data: Buffer): Promise<void>;
  get(importId: string): Promise<Buffer | null>;
  has(importId: string): Promise<boolean>;
  delete(importId: string): Promise<void>;
}

export const IMPORT_ID_RE = /^ci[0-9a-f]{20}$/;
const check = (id: string) => { if (!IMPORT_ID_RE.test(id)) throw new Error("bad import id"); };

export const CYRUS_IMPORT_DIR = cyrusConfig().importDir;

export class FsQuarantine implements QuarantineStore {
  constructor(private dir: string = CYRUS_IMPORT_DIR) {}
  private file(id: string) { check(id); return join(this.dir, `${id}.upload`); }
  async put(id: string, data: Buffer) {
    const f = this.file(id);
    await mkdir(this.dir, { recursive: true, mode: 0o700 });
    const tmp = `${f}.${process.pid}.tmp`;
    await writeFile(tmp, data, { mode: 0o600 });
    await rename(tmp, f);
  }
  async get(id: string) { try { return await readFile(this.file(id)); } catch { return null; } }
  async has(id: string) { try { return (await stat(this.file(id))).isFile(); } catch { return false; } }
  async delete(id: string) { await rm(this.file(id), { force: true }); }
}

export class MemoryQuarantine implements QuarantineStore {
  readonly m = new Map<string, Buffer>();
  async put(id: string, data: Buffer) { check(id); this.m.set(id, Buffer.from(data)); }
  async get(id: string) { return this.m.get(id) ?? null; }
  async has(id: string) { return this.m.has(id); }
  async delete(id: string) { this.m.delete(id); }
}
