// Signed, expiring, scope-checked library file URLs. A URL is `<base>/<token>`; the token is
// base64url(JSON claims) + "." + base64url(HMAC-SHA256(secret, "cyrus-lib-url.v1." + payload)).
// Claims: v, id (catalog sha256), r (variant: "original" or a recipe id), sub (OPAQUE viewer id, an HMAC of the
// host user id: never the user id or email itself), prj (optional project scope), iat, exp (<= 15 min after iat).
// The route re-checks everything at fetch time: signature, expiry, that the signed-in viewer IS `sub`, the entry's
// current status (a removed asset stops serving immediately), and the variant rules (raw audio never).
// Pure apart from node:crypto. HOST SEAM: no Nxeon imports.
import { createHmac, timingSafeEqual } from "node:crypto";
import { RECIPE_IDS, type RecipeId } from "./derive";

export const URL_TTL_DEFAULT_S = 300;
export const URL_TTL_MAX_S = 900;
export type Variant = "original" | RecipeId;
export const VARIANTS: readonly Variant[] = ["original", ...RECIPE_IDS];
export type UrlClaims = { v: 1; id: string; r: Variant; sub: string; prj: string | null; iat: number; exp: number };

const b64 = (b: Buffer) => b.toString("base64url");
const mac = (secret: string, payload: string) => createHmac("sha256", secret).update(`cyrus-lib-url.v1.${payload}`).digest();

/** The opaque per-viewer id used in URLs (and nowhere else): stable for a user, meaningless without the secret. */
export const opaqueViewer = (userId: string, secret: string) => b64(createHmac("sha256", secret).update(`cyrus-lib-viewer.v1.${userId}`).digest()).slice(0, 24);

export function signLibraryUrl(c: { id: string; variant: Variant; sub: string; prj?: string | null; ttlSec?: number }, secret: string, now = Date.now()): string {
  if (secret.length < 32) throw new Error("library URL secret must be at least 32 characters");
  if (!/^[0-9a-f]{64}$/.test(c.id)) throw new Error("bad catalog id");
  if (!VARIANTS.includes(c.variant)) throw new Error("bad variant");
  if (!/^[A-Za-z0-9_-]{8,64}$/.test(c.sub)) throw new Error("bad viewer scope");
  const ttl = Math.max(1, Math.min(URL_TTL_MAX_S, Math.floor(c.ttlSec ?? URL_TTL_DEFAULT_S)));
  const iat = Math.floor(now / 1000);
  const claims: UrlClaims = { v: 1, id: c.id, r: c.variant, sub: c.sub, prj: c.prj ?? null, iat, exp: iat + ttl };
  const payload = b64(Buffer.from(JSON.stringify(claims)));
  return `${payload}.${b64(mac(secret, payload))}`;
}

export type UrlCheck = { ok: true; claims: UrlClaims } | { ok: false; code: "malformed" | "bad_signature" | "expired" | "not_yet_valid" | "wrong_viewer" };

/** Verify a token; `viewer` (opaque id of whoever is signed in now) must equal the token's sub. */
export function verifyLibraryUrl(token: string, secret: string, viewer: string | null, now = Date.now()): UrlCheck {
  if (typeof token !== "string" || token.length > 1024) return { ok: false, code: "malformed" };
  const m = /^([A-Za-z0-9_-]+)\.([A-Za-z0-9_-]{43})$/.exec(token);
  if (!m || secret.length < 32) return { ok: false, code: "malformed" };
  const want = mac(secret, m[1]), got = Buffer.from(m[2], "base64url");
  if (got.length !== want.length || !timingSafeEqual(got, want)) return { ok: false, code: "bad_signature" };
  let c: UrlClaims;
  try { c = JSON.parse(Buffer.from(m[1], "base64url").toString("utf8")) as UrlClaims; } catch { return { ok: false, code: "malformed" }; }
  if (c?.v !== 1 || !/^[0-9a-f]{64}$/.test(c.id) || !VARIANTS.includes(c.r) || typeof c.sub !== "string" || !Number.isInteger(c.exp) || !Number.isInteger(c.iat) || c.exp - c.iat > URL_TTL_MAX_S) return { ok: false, code: "malformed" };
  const t = Math.floor(now / 1000);
  if (t >= c.exp) return { ok: false, code: "expired" };
  if (c.iat > t + 60) return { ok: false, code: "not_yet_valid" };
  if (!viewer || viewer !== c.sub) return { ok: false, code: "wrong_viewer" };
  return { ok: true, claims: c };
}
// Cyrus asset library backend (r26): serves one signed, expiring, viewer-scoped library file. Off -> 404.
// Logic + checks: lib/cyrus/library/backend/http.ts.
import { handleFile } from "@/lib/cyrus/library/backend/http";
import { libraryHttpDeps } from "@/lib/cyrus/library/backend/runtime";

export const dynamic = "force-dynamic";

export async function GET(req: Request, ctx: { params: Promise<{ token: string }> }) {
  return handleFile(req, await ctx.params, libraryHttpDeps());
}
// HTTP handlers of the asset library backend (thin routes under app/api/cyrus/library/v2/ call these).
//   POST /api/cyrus/library/v2/url          { id, variant }            -> { url, expiresAt }   (signs a file URL)
//   GET  /api/cyrus/library/v2/file/<token>                            -> the bytes             (verifies + serves)
//   POST /api/cyrus/library/v2/report       { id, reason, note? }      -> { ok, held }
// Off (CYRUS_LIBRARY_BACKEND unset) or not a studio viewer: 404, as if the routes did not exist. Every request:
// viewer -> rate limit -> validation -> canServe (status, variant, plan gate, licence tiers, proprietary clearance)
// -> action. The file route re-checks everything at fetch time (a takedown is effective immediately: 410).
// HOST SEAM: deps injected (./runtime.ts builds the real ones).
import type { CatalogIndex } from "../v2/retrieval";
import type { CatalogStore } from "../v2/pipeline";
import type { LibraryFlags } from "./flags";
import { canServe, type LibraryStore } from "./library-store";
import { report } from "./moderation";
import type { LibraryRecords } from "./records";
import { opaqueViewer, signLibraryUrl, verifyLibraryUrl, VARIANTS, URL_TTL_DEFAULT_S, type Variant } from "./signed-url";

export type LibraryBackend = { index: CatalogIndex; catalog: CatalogStore; store: LibraryStore; records: LibraryRecords };
export type LibraryHttpDeps = {
  flags: LibraryFlags;
  viewer(): Promise<{ userId: string } | null>;
  planOf(userId: string): Promise<unknown>;
  backend(): LibraryBackend | null;
  rateLimit(key: string, max: number, windowMs: number): { ok: boolean; retryAfterSec?: number };
  now?: () => number;
};

const H = { "cache-control": "no-store", "x-robots-tag": "noindex" };
const json = (status: number, body: unknown) => Response.json(body, { status, headers: H });
const NOT_FOUND = () => json(404, { error: "Not found" });
export const FILE_ROUTE = "/api/cyrus/library/v2/file/";

async function readBody(req: Request): Promise<Record<string, unknown> | null> {
  const t = await req.text().catch(() => "");
  if (t.length > 8192) return null;
  try { const v = JSON.parse(t || "{}"); return v && typeof v === "object" && !Array.isArray(v) ? v : null; } catch { return null; }
}

async function gate(deps: LibraryHttpDeps, key: string, max: number) {
  if (!deps.flags.enabled) return { fail: NOT_FOUND() } as const;
  const v = await deps.viewer().catch(() => null);
  if (!v) return { fail: NOT_FOUND() } as const;
  const rl = deps.rateLimit(`cyrus:library:${key}:${v.userId}`, max, 60_000);
  if (!rl.ok) return { fail: json(429, { error: "Too many requests", retryAfterSec: rl.retryAfterSec ?? 60 }) } as const;
  const b = deps.backend();
  if (!b) return { fail: json(503, { error: "The asset library is not available on this server yet." }) } as const;
  return { viewer: v, backend: b } as const;
}

export async function handleSignUrl(req: Request, deps: LibraryHttpDeps): Promise<Response> {
  const g = await gate(deps, "url", 240);
  if ("fail" in g) return g.fail!;
  if (!deps.flags.urlSecret) return json(503, { error: "File URLs are not configured (CYRUS_LIBRARY_URL_SECRET)." });
  const b = await readBody(req);
  const id = String(b?.id ?? "").replace(/^cat:/, ""), variant = String(b?.variant ?? "thumb@1") as Variant;
  if (!/^[0-9a-f]{64}$/.test(id) || !VARIANTS.includes(variant)) return json(400, { error: "id must be a catalog id and variant one of " + VARIANTS.join(", ") });
  const e = await g.backend.index.get(id);
  if (!e) return json(404, { error: "Not found" });
  const plan = await deps.planOf(g.viewer.userId).catch(() => null);
  const d = canServe(e, variant, { signedIn: true, plan }, { proprietaryCleared: deps.flags.proprietaryCleared });
  if (!d.ok) return json(d.status, { error: d.reason, code: d.code });
  const now = deps.now?.() ?? Date.now();
  const token = signLibraryUrl({ id, variant, sub: opaqueViewer(g.viewer.userId, deps.flags.urlSecret), ttlSec: URL_TTL_DEFAULT_S }, deps.flags.urlSecret, now);
  return json(200, { url: FILE_ROUTE + token, expiresAt: new Date(now + URL_TTL_DEFAULT_S * 1000).toISOString() });
}

export async function handleFile(_req: Request, p: { token: string }, deps: LibraryHttpDeps): Promise<Response> {
  const g = await gate(deps, "file", 600);
  if ("fail" in g) return g.fail!;
  if (!deps.flags.urlSecret) return NOT_FOUND();
  const now = deps.now?.() ?? Date.now();
  const v = verifyLibraryUrl(p.token, deps.flags.urlSecret, opaqueViewer(g.viewer.userId, deps.flags.urlSecret), now);
  if (!v.ok) return json(v.code === "expired" ? 410 : 403, { error: v.code === "expired" ? "This link has expired." : "This link is not valid for you.", code: v.code });
  const e = await g.backend.index.get(v.claims.id);
  if (!e) return NOT_FOUND();
  const plan = await deps.planOf(g.viewer.userId).catch(() => null);
  const d = canServe(e, v.claims.r, { signedIn: true, plan }, { proprietaryCleared: deps.flags.proprietaryCleared });
  if (!d.ok) return json(d.status, { error: d.reason, code: d.code });
  const bytes = await g.backend.store.bytesFor(e, v.claims.r);
  if (!bytes.ok) return json(bytes.code === "tool_missing" || bytes.code === "not_available" ? 404 : 502, { error: "This file is not available.", code: bytes.code });
  const left = Math.max(0, v.claims.exp - Math.floor(now / 1000));
  const download = v.claims.r === "original" || v.claims.r === "bundle@1" || v.claims.r === "glb-opt@1";
  const ext = v.claims.r === "bundle@1" ? "zip" : v.claims.r === "thumb@1" ? "png" : v.claims.r === "preview-ogg@1" ? "ogg" : v.claims.r === "glb-opt@1" ? "glb" : e.tech.format.toLowerCase();
  return new Response(Buffer.from(bytes.bytes), {
    status: 200,
    headers: {
      "content-type": bytes.mime, "content-length": String(bytes.bytes.length),
      "cache-control": `private, max-age=${left}`, "x-content-type-options": "nosniff", "x-robots-tag": "noindex",
      "content-security-policy": "default-src 'none'; sandbox", "cross-origin-resource-policy": "same-origin",
      "content-disposition": `${download ? "attachment" : "inline"}; filename="${e.id.slice(0, 12)}.${ext.replace(/[^a-z0-9]/g, "")}"`,
    },
  });
}

export async function handleReport(req: Request, deps: LibraryHttpDeps): Promise<Response> {
  const g = await gate(deps, "report", 20);
  if ("fail" in g) return g.fail!;
  if (!deps.flags.urlSecret) return json(503, { error: "Reports are not configured yet." });
  const b = await readBody(req);
  const id = String(b?.id ?? "").replace(/^cat:/, "");
  if (!/^[0-9a-f]{64}$/.test(id)) return json(400, { error: "id must be a catalog id" });
  const r = await report({ catalog: g.backend.catalog, index: g.backend.index, records: g.backend.records, now: () => new Date(deps.now?.() ?? Date.now()) },
    { entryId: id, reporter: `u:${opaqueViewer(g.viewer.userId, deps.flags.urlSecret).toLowerCase().replace(/[^a-z0-9_-]/g, "_")}`, reason: String(b?.reason ?? ""), note: typeof b?.note === "string" ? b.note : null });
  if (!r.ok) return json(r.code === "not_found" ? 404 : 400, { error: r.error });
  return json(200, { ok: true, held: r.held, duplicate: !r.created });
}

// LibraryStore: the bytes side of the asset library, on the ObjectStore contract (./objects.ts).
//   originals    a contribution / copied original lives in the object store at sha256/<entry id>; a staged asset is
//                read from the READ-ONLY staging volume (path-confined, sha256-checked). Folder kinds (ambientCG /
//                Poly Haven PBR sets, HDRIs, decals) have no single original: their id is the upstream zip hash, so
//                they are served as the deterministic bundle@1 derivative instead.
//   derivatives  lazily generated by ./derive.ts recipes on first request, cached content-addressed, recorded in
//                LibraryRecords.derivatives (last use tracked for retention).
//   caps         per-kind original caps (checked on the file size before reading) + per-recipe output caps.
//   retention    sweep(): derivative rows unused for RETENTION.derivativeUnusedDays are dropped (objects with no
//                other reference deleted: they regenerate on demand); a REMOVED community asset's own object is
//                deleted after RETENTION.removedGraceDays. Staged files are never touched. Projects that used an
//                asset keep their own copy (CyrusProjectAsset), so nothing here can break an existing mod.
//   serving      canServe(): status, variant and plan/licence rules; raw audio is NEVER served (preview-ogg only),
//                the proprietary library never as an original and only once cleared.
// SERVER ONLY. HOST SEAM: no Nxeon imports.
import path from "node:path";
import { promises as fsp } from "node:fs";
import { access } from "../v2/tools";
import type { CatalogEntry, CatalogKind } from "../v2/entry";
import type { CatalogStore } from "../v2/pipeline";
import { BUNDLE_EXT, isFolderEntry, RECIPE_MIME, recipesFor, runRecipe, type DeriveTools, type RecipeId } from "./derive";
import { keyOf, type LibraryObjectStore, type StagingSource } from "./objects";
import type { LibraryRecords } from "./records";
import type { Variant } from "./signed-url";

const MB = 1024 * 1024;
export const ORIGINAL_MAX_BYTES: Readonly<Record<CatalogKind, number>> = {
  model: 96 * MB, "texture-set": 160 * MB, texture: 32 * MB, sprite: 8 * MB, hdri: 160 * MB, decal: 64 * MB, sound: 48 * MB, music: 96 * MB,
  flipbook: 64 * MB, "particle-texture": 16 * MB, "animation-clip": 96 * MB, "animated-model": 96 * MB, "motion-preset": 1 * MB, "effect-preset": 1 * MB,
};
export const RETENTION = { derivativeUnusedDays: 30, removedGraceDays: 30 } as const;
const DAY = 86_400_000;

export type Bytes = { ok: true; bytes: Uint8Array; mime: string; from: "object" | "staging" | "cache" | "generated"; tool?: string };
export type Miss = { ok: false; code: string; error: string };

const MIME: Record<string, string> = { png: "image/png", jpg: "image/jpeg", jpeg: "image/jpeg", glb: "model/gltf-binary", gltf: "model/gltf+json", ogg: "audio/ogg", wav: "audio/wav", mp3: "audio/mpeg", json: "application/json", svg: "image/svg+xml" };
export const mimeOf = (e: Pick<CatalogEntry, "tech">) => MIME[e.tech.format.toLowerCase()] ?? "application/octet-stream";

export class LibraryStore {
  private readonly now: () => Date;
  constructor(private readonly o: { objects: LibraryObjectStore; staging: StagingSource | null; records: LibraryRecords; tools: DeriveTools; now?: () => Date }) {
    this.now = o.now ?? (() => new Date());
  }

  /** The original bytes of a single-file entry (object store first, then the staged file). */
  async original(e: CatalogEntry): Promise<Bytes | Miss> {
    if (isFolderEntry(e)) return { ok: false, code: "folder", error: "a folder entry has no single original; use bundle@1" };
    const cap = ORIGINAL_MAX_BYTES[e.kind];
    const key = keyOf(e.id);
    const size = await this.o.objects.size(key);
    if (size != null) {
      if (size > cap) return { ok: false, code: "too_large", error: `${size} bytes is over the ${cap}-byte cap` };
      const b = await this.o.objects.get(key);
      if (b) return { ok: true, bytes: b, mime: mimeOf(e), from: "object" };
    }
    if (!this.o.staging) return { ok: false, code: "missing", error: "no stored copy and no staging volume" };
    const r = await this.o.staging.read(e.provenance.path, e.id, cap);
    return r.ok ? { ok: true, bytes: r.bytes, mime: mimeOf(e), from: "staging" } : { ok: false, code: r.code, error: r.error };
  }

  /** Copy a staged original into the object store (the owner's "make it self-contained" step; never moves the file). */
  async persistOriginal(e: CatalogEntry): Promise<{ ok: true; key: string; created: boolean } | Miss> {
    const key = keyOf(e.id);
    if (await this.o.objects.has(key)) return { ok: true, key, created: false };
    const b = await this.original(e);
    if (!b.ok) return b;
    return { ok: true, key: await this.o.objects.put(b.bytes), created: true };
  }

  private async stagedFile(rel: string, maxBytes: number): Promise<Uint8Array | null> {
    if (!this.o.staging) return null;
    const r = await this.o.staging.resolve(rel);
    if (!r.ok || r.size > maxBytes) return null;
    return fsp.readFile(r.path);
  }
  private async stagedDir(rel: string): Promise<string[]> { return this.o.staging ? this.o.staging.listDir(rel) : []; }

  /** Where a thumbnail comes from (see ./derive.ts): the PNG itself, a sibling image, or the folder's preview / colour map. */
  async thumbSource(e: CatalogEntry): Promise<{ bytes: Uint8Array; ext: "png" | "jpg" } | null> {
    const fmt = e.tech.format.toLowerCase();
    const flat = e.kind === "sprite" || e.kind === "texture" || e.kind === "decal" || e.kind === "flipbook" || e.kind === "particle-texture";
    if (flat && (fmt === "png" || fmt === "jpg" || fmt === "jpeg")) { const b = await this.original(e); return b.ok ? { bytes: b.bytes, ext: fmt === "png" ? "png" : "jpg" } : null; }
    const p = e.provenance.path;
    if (!p) return null;
    if (e.kind === "model" || e.kind === "animated-model") {
      const sib = p.replace(/\.[a-z0-9]+$/i, ".png");
      const b = sib !== p ? await this.stagedFile(sib, 16 * MB) : null;
      return b ? { bytes: b, ext: "png" } : null;
    }
    if (isFolderEntry(e)) {
      const names = await this.stagedDir(p);
      const base = path.basename(p);
      const pick = (e.kind === "flipbook" ? names.find((n) => /\.png$/i.test(n)) : undefined) ?? names.find((n) => n === `${base}.png`) ?? names.find((n) => /_(color|basecolor|albedo|diff(use)?)\.(jpe?g|png)$/i.test(n)) ?? names.find((n) => /_tonemapped\.(jpe?g|png)$/i.test(n));
      if (!pick) return null;
      const b = await this.stagedFile(`${p}/${pick}`, 64 * MB);
      return b ? { bytes: b, ext: /\.png$/i.test(pick) ? "png" : "jpg" } : null;
    }
    return null;
  }

  /** The folder's bundle files (images + MaterialX), total capped at the kind's original cap. */
  async folder(e: CatalogEntry): Promise<{ name: string; bytes: Uint8Array }[] | null> {
    if (!isFolderEntry(e) || !e.provenance.path) return null;
    const cap = ORIGINAL_MAX_BYTES[e.kind];
    const out: { name: string; bytes: Uint8Array }[] = [];
    let total = 0;
    for (const n of await this.stagedDir(e.provenance.path)) {
      if (!BUNDLE_EXT.test(n)) continue;
      const b = await this.stagedFile(`${e.provenance.path}/${n}`, cap - total);
      if (!b) return null; // over the cap or unreadable: no partial bundles
      total += b.length; out.push({ name: n, bytes: b });
    }
    return out.length ? out : null;
  }

  /** A derivative: cached object, or generated now (deterministic recipe) and cached. */
  async derivative(e: CatalogEntry, recipe: RecipeId): Promise<Bytes | Miss> {
    if (!recipesFor(e).includes(recipe)) return { ok: false, code: "not_available", error: `${recipe} does not apply to a ${e.kind}` };
    const now = this.now();
    const row = await this.o.records.derivatives.get(e.id, recipe);
    if (row) {
      const b = await this.o.objects.get(row.objectKey);
      if (b) { await this.o.records.derivatives.touch(e.id, recipe, now); return { ok: true, bytes: b, mime: RECIPE_MIME[recipe], from: "cache", tool: row.tool }; }
      await this.o.records.derivatives.delete(e.id, recipe); // object gone or corrupt: regenerate
    }
    const r = await runRecipe(recipe, {
      entry: e,
      original: async () => { const b = await this.original(e); return b.ok ? b.bytes : null; },
      thumbSource: () => this.thumbSource(e),
      folder: () => this.folder(e),
    }, this.o.tools);
    if (!r.ok) return { ok: false, code: r.code, error: r.error };
    const objectKey = await this.o.objects.put(r.bytes);
    await this.o.records.derivatives.put({ entryId: e.id, recipe, objectKey, bytes: r.bytes.length, tool: r.tool, createdAt: now, lastUsedAt: now });
    return { ok: true, bytes: r.bytes, mime: RECIPE_MIME[recipe], from: "generated", tool: r.tool };
  }

  /** What a signed URL serves (the caller ran canServe first). */
  async bytesFor(e: CatalogEntry, variant: Variant): Promise<Bytes | Miss> {
    return variant === "original" ? this.original(e) : this.derivative(e, variant);
  }

  /** Takedown: drop every cached derivative of an entry now (stops serving at once; objects shared elsewhere stay). */
  async purgeDerivatives(entryId: string): Promise<number> {
    let n = 0;
    for (const d of await this.o.records.derivatives.forEntry(entryId)) {
      await this.o.records.derivatives.delete(entryId, d.recipe);
      if ((await this.o.records.derivatives.refs(d.objectKey)) === 0) await this.o.objects.delete(d.objectKey);
      n++;
    }
    return n;
  }

  /** Retention sweep (idempotent). Never touches the staging volume or project copies. */
  async sweep(o: { catalog?: CatalogStore; limit?: number } = {}): Promise<{ derivativesDropped: number; objectsDeleted: number; removedOriginalsDeleted: number; bytesFreed: number }> {
    const now = this.now(), limit = o.limit ?? 5000;
    let dropped = 0, deleted = 0, removedDeleted = 0, freed = 0;
    for (const d of await this.o.records.derivatives.unusedSince(new Date(+now - RETENTION.derivativeUnusedDays * DAY), limit)) {
      await this.o.records.derivatives.delete(d.entryId, d.recipe); dropped++;
      if ((await this.o.records.derivatives.refs(d.objectKey)) === 0 && (await this.o.objects.has(d.objectKey))) { await this.o.objects.delete(d.objectKey); deleted++; freed += d.bytes; }
    }
    if (o.catalog) {
      let cursor: string | null = null;
      for (let page = 0; page < 100; page++) {
        const rows: CatalogEntry[] = await o.catalog.listByStatus("removed", cursor, 500);
        if (!rows.length) break;
        cursor = rows[rows.length - 1].id;
        for (const e of rows) {
          if (e.licence.tier !== "user-contributed") continue; // pack assets: the staged file is not ours to delete
          const at = (await this.o.records.log.list({ entryId: e.id, actions: ["takedown"], limit: 1 }))[0]?.at;
          if (!at || +now - +at < RETENTION.removedGraceDays * DAY) continue;
          const key = keyOf(e.id), size = await this.o.objects.size(key);
          if (size != null) { await this.o.objects.delete(key); removedDeleted++; freed += size; }
        }
      }
    }
    return { derivativesDropped: dropped, objectsDeleted: deleted, removedOriginalsDeleted: removedDeleted, bytesFreed: freed };
  }
}

export type ServeDecision = { ok: true } | { ok: false; status: 400 | 403 | 404 | 410; code: string; reason: string };

/**
 * May this viewer get this variant of this entry? (checked when a URL is signed AND again when it is fetched)
 *  - only published entries are served; removed answers 410 (takedown is immediate), held/pending 404
 *  - sound/music: never the raw file, only preview-ogg@1
 *  - proprietary-nxeon: never an original; any preview only when the owner cleared the library
 *  - the plan gate + licence tiers of the catalog tools (sounds Saka+, visuals the top plan; free/Katara nothing)
 */
export function canServe(e: CatalogEntry, variant: Variant, viewer: { signedIn: boolean; plan: unknown }, flags: { proprietaryCleared: boolean }): ServeDecision {
  if (!viewer.signedIn) return { ok: false, status: 403, code: "sign_in", reason: "Sign in to use the asset library." };
  if (e.status === "removed") return { ok: false, status: 410, code: "removed", reason: "This asset was removed from the library." };
  if (e.status !== "published") return { ok: false, status: 404, code: "not_found", reason: "Not found." };
  const audio = e.kind === "sound" || e.kind === "music";
  if (audio && variant !== "preview-ogg@1") return { ok: false, status: 403, code: "raw_audio", reason: "Library audio is only served as a preview; builds use it through the render path." };
  if (e.licence.tier === "proprietary-nxeon") {
    if (variant === "original" || variant === "bundle@1") return { ok: false, status: 403, code: "never_raw", reason: "The Nxeon library is never served as original files." };
    if (!flags.proprietaryCleared) return { ok: false, status: 403, code: "not_cleared", reason: "This part of the library is not available yet." };
  }
  if (variant === "original" && isFolderEntry(e)) return { ok: false, status: 400, code: "use_bundle", reason: "This asset is a set of files; ask for bundle@1." };
  if (variant !== "original" && !recipesFor(e).includes(variant)) return { ok: false, status: 400, code: "no_variant", reason: `${variant} does not exist for a ${e.kind}.` };
  const a = access(viewer.plan, flags.proprietaryCleared);
  if (!a.plan) return { ok: false, status: 403, code: "plan_unknown", reason: "We couldn't confirm your Cyrus plan right now." };
  if (!a.kinds.includes(e.kind)) return { ok: false, status: 403, code: "asset_locked", reason: audio ? "Library sounds need the Saka plan or higher." : "Library models and textures need the All models plan." };
  if (!a.tiers.includes(e.licence.tier)) return { ok: false, status: 403, code: "tier_locked", reason: "This asset is not available on your plan." };
  return { ok: true };
}
// Moderation of the community library: reports, the owner's hold queue, takedown / removal, restore.
//   report()    one open report per (asset, reporter). A legal reason (copyright, trademark) or open reports from
//               REPORT_HOLD_THRESHOLD different reporters move a published asset to `held` at once (owner reviews).
//   holdQueue() held entries, oldest first, with their flags and open reports: what the owner looks at.
//   release()   owner: held -> published. Hold flags become `cleared:<rule>` (an entry with a hold: flag can never be
//               published, see entry.ts), so the decision stays visible.
//   takedown()  owner / legal: any status -> removed, immediately: the index stops returning it, cached derivatives
//               are purged (signed URLs answer 410), open reports are actioned, and every project that used it is
//               MARKED (upstream = removed). Marked projects KEEP WORKING from their own copy (CyrusProjectAsset):
//               installing, rebuilding and exporting are never broken by a takedown (./use.ts resolveSlotForBuild).
//               A legal takedown is flagged in the log so the owner can follow up with those projects by hand.
//   restore()   removed -> held (never straight back to published).
// Every action appends a moderation log row (the takedown log). HOST SEAM: actor ids are opaque strings.
import type { CatalogEntry } from "../v2/entry";
import type { CatalogStore } from "../v2/pipeline";
import type { CatalogIndex } from "../v2/retrieval";
import type { LibraryStore } from "./library-store";
import { REPORT_REASONS, type LibraryRecords, type ModerationRow, type ReportReason, type ReportRow } from "./records";

export const REPORT_HOLD_THRESHOLD = 3;
export const LEGAL_REASONS: readonly ReportReason[] = ["copyright", "trademark"];

export type ModerationDeps = { catalog: CatalogStore; index?: CatalogIndex; records: LibraryRecords; store?: LibraryStore; now: () => Date };
type Fail = { ok: false; code: "not_found" | "bad_request" | "bad_state"; error: string };

const one = async (d: ModerationDeps, id: string) => (await d.catalog.getMany([id]))[0] ?? null;
async function write(d: ModerationDeps, e: CatalogEntry) { await d.catalog.upsertMany([e]); if (d.index) await d.index.upsert([e]); }

export async function report(d: ModerationDeps, input: { entryId: string; reporter: string; reason: string; note?: string | null }): Promise<{ ok: true; report: ReportRow; created: boolean; held: boolean } | Fail> {
  if (!(REPORT_REASONS as readonly string[]).includes(input.reason)) return { ok: false, code: "bad_request", error: `reason must be one of ${REPORT_REASONS.join(", ")}` };
  if (!/^[a-z0-9_:-]{4,80}$/.test(input.reporter)) return { ok: false, code: "bad_request", error: "reporter must be an opaque id" };
  const e = await one(d, input.entryId);
  if (!e || e.status === "removed") return { ok: false, code: "not_found", error: "no such asset" };
  const now = d.now();
  const r = await d.records.reports.add({ entryId: e.id, reporter: input.reporter, reason: input.reason as ReportReason, note: input.note?.slice(0, 500) ?? null, createdAt: now });
  if (r.created) await d.records.log.append({ entryId: e.id, action: "report", from: e.status, to: e.status, by: input.reporter, reason: input.reason, legal: LEGAL_REASONS.includes(input.reason as ReportReason), dependents: 0, at: now });
  let held = false;
  if (e.status === "published") {
    const open = await d.records.reports.open(e.id);
    const reporters = new Set(open.map((x) => x.reporter)).size;
    const legal = open.some((x) => LEGAL_REASONS.includes(x.reason));
    if (legal || reporters >= REPORT_HOLD_THRESHOLD) {
      const reason = legal ? `reported (${open.filter((x) => LEGAL_REASONS.includes(x.reason)).map((x) => x.reason).join(", ")}): owner review` : `${reporters} reports: owner review`;
      await write(d, { ...e, status: "held", statusReason: reason, flags: [...new Set([...e.flags, "hold:reports"])].slice(0, 12) });
      await d.records.log.append({ entryId: e.id, action: "hold", from: "published", to: "held", by: "system:reports", reason, legal, dependents: 0, at: now });
      held = true;
    }
  }
  return { ok: true, report: r.row, created: r.created, held };
}

export type HoldItem = { entry: CatalogEntry; flags: string[]; reason: string | null; reports: ReportRow[] };
export async function holdQueue(d: ModerationDeps, opts: { cursor?: string | null; limit?: number } = {}): Promise<HoldItem[]> {
  const rows = await d.catalog.listByStatus("held", opts.cursor ?? null, Math.min(200, opts.limit ?? 50));
  const out: HoldItem[] = [];
  for (const e of rows) out.push({ entry: e, flags: e.flags, reason: e.statusReason, reports: await d.records.reports.open(e.id, 20) });
  return out;
}

export async function release(d: ModerationDeps, input: { entryId: string; by: string; note?: string }): Promise<{ ok: true; entry: CatalogEntry } | Fail> {
  const e = await one(d, input.entryId);
  if (!e) return { ok: false, code: "not_found", error: "no such asset" };
  if (e.status !== "held") return { ok: false, code: "bad_state", error: `only a held asset can be released (this one is ${e.status})` };
  const now = d.now();
  const n: CatalogEntry = { ...e, status: "published", statusReason: `released by the owner${input.note ? `: ${input.note}` : ""}`.slice(0, 300), flags: e.flags.map((f) => (f.startsWith("hold:") ? `cleared:${f.slice(5)}` : f)) };
  await write(d, n);
  await d.records.reports.resolve(e.id, "dismissed", input.by, now);
  await d.records.uses.markUpstream(e.id, "published", now);
  await d.records.log.append({ entryId: e.id, action: "release", from: "held", to: "published", by: input.by, reason: input.note ?? null, legal: false, dependents: 0, at: now });
  return { ok: true, entry: n };
}

export async function takedown(d: ModerationDeps, input: { entryId: string; by: string; reason: string; legal?: boolean }): Promise<{ ok: true; entry: CatalogEntry; dependents: number; purged: number } | Fail> {
  if (!input.reason?.trim()) return { ok: false, code: "bad_request", error: "a takedown needs a reason" };
  const e = await one(d, input.entryId);
  if (!e) return { ok: false, code: "not_found", error: "no such asset" };
  if (e.status === "removed") return { ok: false, code: "bad_state", error: "already removed" };
  const now = d.now();
  const n: CatalogEntry = { ...e, status: "removed", statusReason: `${input.legal ? "legal takedown" : "removed"}: ${input.reason}`.slice(0, 300) };
  await write(d, n);
  const purged = d.store ? await d.store.purgeDerivatives(e.id) : 0;
  const dependents = await d.records.uses.markUpstream(e.id, "removed", now);
  await d.records.reports.resolve(e.id, "actioned", input.by, now);
  await d.records.log.append({ entryId: e.id, action: "takedown", from: e.status, to: "removed", by: input.by, reason: input.reason.slice(0, 300), legal: !!input.legal, dependents, at: now });
  return { ok: true, entry: n, dependents, purged };
}

export async function restore(d: ModerationDeps, input: { entryId: string; by: string; reason: string }): Promise<{ ok: true; entry: CatalogEntry } | Fail> {
  const e = await one(d, input.entryId);
  if (!e) return { ok: false, code: "not_found", error: "no such asset" };
  if (e.status !== "removed") return { ok: false, code: "bad_state", error: "only a removed asset can be restored" };
  const now = d.now();
  const n: CatalogEntry = { ...e, status: "held", statusReason: `restored for review: ${input.reason}`.slice(0, 300) };
  await write(d, n);
  await d.records.log.append({ entryId: e.id, action: "restore", from: "removed", to: "held", by: input.by, reason: input.reason.slice(0, 300), legal: false, dependents: 0, at: now });
  return { ok: true, entry: n };
}

export async function takedownLog(d: Pick<ModerationDeps, "records">, limit = 100): Promise<ModerationRow[]> {
  return d.records.log.list({ actions: ["takedown", "restore", "hold", "release"], limit });
}

// AUTOMATIC community contribution (owner decision 2026-10-10: assets made in Cyrus join the library with no opt-in).
// What the studios / meshgen hand in: the bytes + the asset manifest's legal class and provenance. Steps:
//   0. switch: CYRUS_LIBRARY_CONTRIBUTE off -> nothing is written ("off")
//   1. eligibility (lib/cyrus/assets3d/manifest.ts libraryEligible): only user-original / ai-generated-for-user
//      content authored inside Cyrus from nothing outside it. Never game-derived, third-party-licensed, imported,
//      uploaded, template-based or derived (derivedFrom non-empty) content -> "ineligible", nothing stored
//   2. exact dedupe on the content hash: already in the catalog -> "duplicate" (no second entry); an asset that was
//      TAKEN DOWN cannot come back by contributing the same bytes again -> "blocked"
//   3. near dedupe (./fingerprint.ts): near a published asset -> stored with duplicateOf (never shown twice);
//      near a REMOVED asset -> held for the owner (a slightly edited copy of something taken down)
//   4. size cap, bytes into the object store (sha256/<id>), stage A metadata (zero tokens), strict content filters
//      (adult -> removed; real-weapon / trademark / extremist / drugs / mature violence -> held for owner review;
//      quality hard fail -> held), status pending-checks -> published | held | removed
//   5. provenance (studio, derivedFrom = []), legal class, opaque contributor and the moderation log row are kept
// HOST SEAM: no Nxeon imports; the contributor id is opaque (the host maps its user to it).
import type { AssetProfile } from "../../adapters/asset-profile";
import { libraryEligible, type AssetManifest } from "../../assets3d/manifest";
import { sha256Hex } from "../../jobs/asset-jobs";
import type { CatalogEntry, CatalogKind } from "../v2/entry";
import { audioFacts, glbFacts, pngFacts, wavDecode } from "../v2/extract";
import type { ContentFilter } from "../v2/filters";
import { contribute, type CatalogStore } from "../v2/pipeline";
import type { CatalogIndex } from "../v2/retrieval";
import type { Measured } from "../v2/stage-a";
import { audioEnv64, hamming64, imageDhash64, modelFactsKey, motionFactsKey, NEAR_HAMMING } from "./fingerprint";
import { ORIGINAL_MAX_BYTES } from "./library-store";
import type { LibraryObjectStore } from "./objects";
import type { FingerprintRow, LibraryRecords } from "./records";

export const CONTRIBUTION_STUDIOS = ["texture", "model", "meshgen", "sound", "motion"] as const;
export type ContributionStudio = (typeof CONTRIBUTION_STUDIOS)[number];
const KIND_OF: Record<ContributionStudio, readonly CatalogKind[]> = { texture: ["sprite", "texture"], model: ["model"], meshgen: ["model"], sound: ["sound", "music"], motion: ["motion-preset", "effect-preset", "flipbook"] };
const FORMATS: Record<CatalogKind, readonly string[]> = { model: ["glb"], sprite: ["png"], texture: ["png"], sound: ["ogg", "wav"], music: ["ogg", "wav"], "motion-preset": ["json"], "effect-preset": ["json"], flipbook: ["png"], "particle-texture": ["png"], "animation-clip": [], "animated-model": ["glb"], "texture-set": [], hdri: [], decal: [] };

export type ContributionInput = {
  studio: ContributionStudio;
  kind: CatalogKind;
  format: string;
  bytes: Uint8Array;
  /** the asset's name in the project ("banshee_wail", "rusty_crate"): becomes title + path words */
  name: string;
  /** from the asset manifest the studio / meshgen wrote (legal ledger) */
  manifest: Pick<AssetManifest, "legalClass" | "provenance">;
  /** opaque contributor id (never an email or the host's user id) */
  contributorId: string;
  tags?: string[];
  /** facts the studio already measured (render stats); otherwise measured here from the bytes */
  measured?: Measured;
};
export type ContributionOutcome =
  | { outcome: "off" | "ineligible" | "invalid" | "too_large"; reason: string }
  | { outcome: "duplicate" | "blocked"; reason: string; entryId: string }
  | { outcome: "published" | "held" | "removed"; entry: CatalogEntry; nearDuplicateOf: string | null; reason: string | null };

export type ContributionDeps = {
  enabled: boolean;
  catalog: CatalogStore;
  index?: CatalogIndex;
  objects: LibraryObjectStore;
  records: LibraryRecords;
  profiles: readonly AssetProfile[];
  now: () => Date;
  filters?: readonly ContentFilter[];
};

const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 48) || "asset";

/** Measure what the bytes say (zero tokens); a parse failure is reported as `corrupt` (quality hard fail -> held). */
export function measureBytes(kind: CatalogKind, format: string, bytes: Uint8Array): { measured: Measured; fp: Omit<FingerprintRow, "entryId" | "kind"> | null } {
  if (kind === "model") {
    const g = glbFacts(bytes);
    return g.ok ? { measured: { glb: g }, fp: { method: "facts", fp: modelFactsKey(g) } } : { measured: { corrupt: g.error }, fp: null };
  }
  if ((kind === "sprite" || kind === "texture" || kind === "flipbook" || kind === "particle-texture") && format === "png") {
    const p = pngFacts(bytes);
    if (!p.ok) return { measured: { corrupt: p.error }, fp: null };
    const h = imageDhash64(bytes);
    return { measured: { image: { width: p.width, height: p.height, hasAlpha: p.hasAlpha } }, fp: h ? { method: "dhash64", fp: h } : null };
  }
  if ((kind === "sound" || kind === "music") && format === "wav") {
    const w = wavDecode(bytes, { maxSeconds: 900 });
    if (!w.ok) return { measured: { corrupt: w.error }, fp: null };
    const env = audioEnv64(w.mono);
    return { measured: { audio: audioFacts(w.mono, w.sampleRate, w.channels, w.bitDepth) }, fp: env ? { method: "env64", fp: env } : null };
  }
  if (kind === "motion-preset" || kind === "effect-preset") { const k = motionFactsKey(bytes); return k ? { measured: {}, fp: { method: "facts", fp: k } } : { measured: { corrupt: "not valid JSON" }, fp: null }; }
  return { measured: {}, fp: null };
}

/** Near-duplicate of an existing entry? (published copy -> duplicateOf; removed -> hold) */
async function nearMatch(deps: ContributionDeps, kind: CatalogKind, fp: Omit<FingerprintRow, "entryId" | "kind">): Promise<CatalogEntry | null> {
  const cands = await deps.records.fingerprints.candidates(kind, fp.method, fp.fp);
  const close = cands.filter((c) => (fp.method === "facts" ? c.fp === fp.fp : hamming64(c.fp, fp.fp) <= NEAR_HAMMING));
  if (!close.length) return null;
  const entries = await deps.catalog.getMany(close.map((c) => c.entryId));
  // a removed match wins (hold), then the best published one
  return entries.find((e) => e.status === "removed") ?? entries.filter((e) => e.status === "published").sort((a, b) => b.quality.score - a.quality.score)[0] ?? null;
}

export async function contributeAsset(input: ContributionInput, deps: ContributionDeps): Promise<ContributionOutcome> {
  if (!deps.enabled) return { outcome: "off", reason: "automatic contribution is switched off (CYRUS_LIBRARY_CONTRIBUTE)" };
  if (!libraryEligible(input.manifest)) return { outcome: "ineligible", reason: `not eligible: ${input.manifest.legalClass} / ${input.manifest.provenance.source}${input.manifest.provenance.derivedFrom.length ? " / derived" : ""}` };
  if (input.manifest.legalClass !== "user-original" && input.manifest.legalClass !== "ai-generated-for-user") return { outcome: "ineligible", reason: `${input.manifest.legalClass} is not a community class` };
  if (!(CONTRIBUTION_STUDIOS as readonly string[]).includes(input.studio) || !KIND_OF[input.studio].includes(input.kind)) return { outcome: "invalid", reason: `the ${input.studio} studio does not contribute ${input.kind}` };
  const format = input.format.toLowerCase();
  if (!FORMATS[input.kind].includes(format)) return { outcome: "invalid", reason: `${format} is not a library format for ${input.kind}` };
  if (!/^[a-z0-9_-]{4,64}$/.test(input.contributorId)) return { outcome: "invalid", reason: "contributor id must be opaque (4-64 of a-z 0-9 _ -)" };
  if (!input.bytes.length || input.bytes.length > ORIGINAL_MAX_BYTES[input.kind]) return { outcome: "too_large", reason: `${input.bytes.length} bytes (cap ${ORIGINAL_MAX_BYTES[input.kind]})` };

  const id = sha256Hex(input.bytes);
  const [existing] = await deps.catalog.getMany([id]);
  const now = deps.now();
  if (existing) {
    const blocked = existing.status === "removed";
    await deps.records.log.append({ entryId: id, action: "duplicate", from: existing.status, to: existing.status, by: `contributor:${input.contributorId}`, reason: blocked ? "re-contribution of a removed asset refused" : "exact duplicate", legal: false, dependents: 0, at: now });
    return blocked ? { outcome: "blocked", reason: "this asset was removed from the library", entryId: id } : { outcome: "duplicate", reason: "already in the library", entryId: id };
  }

  const m = measureBytes(input.kind, format, input.bytes);
  const measured: Measured = { ...m.measured, ...(input.measured ?? {}) };
  const near = m.fp ? await nearMatch(deps, input.kind, m.fp) : null;
  const studioPack = `cyrus-${input.studio}`;
  const r = await contribute({
    raw: { id, source: "cyrus", pack: studioPack, path: `cyrus/${studioPack}/${slug(input.name)}.${format}`, kind: input.kind, format, sizeBytes: input.bytes.length, tier: "user-contributed", name: input.name.slice(0, 80), tags: input.tags ?? null, licenseSpdx: null, licenseUrl: null, retrievedAt: now.toISOString().slice(0, 10) },
    measured, contributorId: input.contributorId, provenanceSource: input.manifest.provenance.source as "user" | "ai", derivedFrom: input.manifest.provenance.derivedFrom, legalClass: input.manifest.legalClass,
  }, { profiles: deps.profiles, now: now.toISOString(), filters: deps.filters });
  if (!r.entry) return { outcome: "invalid", reason: r.errors.join("; ").slice(0, 300) };
  let entry = r.entry;
  if (near && entry.status !== "removed") {
    if (near.status === "removed") entry = { ...entry, status: "held", statusReason: `near-duplicate of removed asset cat:${near.id}`.slice(0, 300), flags: [...new Set([...entry.flags, "hold:near-removed"])].slice(0, 12) };
    else entry = { ...entry, duplicateOf: near.id };
  }
  // bytes first, records after: a crash between them leaves an unreferenced object (the sweep's business), never an entry without bytes
  if (entry.status !== "removed") await deps.objects.put(input.bytes); // a rejected upload's bytes are not kept; its hash stays as a blocklist row
  await deps.catalog.upsertMany([entry]);
  if (deps.index) await deps.index.upsert([entry]);
  if (m.fp) await deps.records.fingerprints.put({ entryId: id, kind: input.kind, ...m.fp });
  await deps.records.log.append({ entryId: id, action: entry.status === "held" ? "hold" : "contribute", from: "pending-checks", to: entry.status, by: `contributor:${input.contributorId}`, reason: entry.statusReason, legal: false, dependents: 0, at: now });
  return { outcome: entry.status as "published" | "held" | "removed", entry, nearDuplicateOf: near?.id ?? null, reason: entry.statusReason };
}
// Near-duplicate fingerprints for community contributions (zero tokens, deterministic).
//   images  dhash64: grey, box-resized to 9x8, one bit per horizontal gradient; near = Hamming distance <= 6 / 64
//   audio   env64:  65 RMS windows over the clip, one bit per rise/fall (WAV input; Ogg renders use the facts key)
//   models  facts:  triangles, vertices, meshes, bounds to the centimetre (a re-export of the same mesh)
//   motion  facts:  sha256 of the canonical JSON with names / ids / labels stripped (a renamed copy of a preset)
// Exact duplicates are caught earlier by the content hash. Pure (node:crypto only). HOST SEAM: no Nxeon imports.
import { createHash } from "node:crypto";
import { decodePng } from "../png-decode";
import type { GlbFacts } from "../v2/extract";

export const NEAR_HAMMING = 6;

export function hamming64(a: string, b: string): number {
  let d = 0;
  for (let i = 0; i < 16; i += 4) { let x = parseInt(a.slice(i, i + 4), 16) ^ parseInt(b.slice(i, i + 4), 16); while (x) { d += x & 1; x >>>= 1; } }
  return d;
}
const bitsHex = (bits: boolean[]) => { let h = ""; for (let i = 0; i < 64; i += 4) h += ((+bits[i] << 3) | (+bits[i + 1] << 2) | (+bits[i + 2] << 1) | +bits[i + 3]).toString(16); return h; };

export function imageDhash64(png: Uint8Array): string | null {
  const d = decodePng(Buffer.from(png), { maxBytes: 32 * 1024 * 1024, sizes: [], maxChunks: 4096, anySize: { maxSide: 8192, maxPixels: 40_000_000 } });
  if (!d.ok) return null;
  const { width: w, height: h } = d, px = d.raster.px;
  const g = new Float64Array(9 * 8);
  for (let y = 0; y < 8; y++) for (let x = 0; x < 9; x++) {
    const x0 = Math.floor((x * w) / 9), x1 = Math.max(x0 + 1, Math.floor(((x + 1) * w) / 9)), y0 = Math.floor((y * h) / 8), y1 = Math.max(y0 + 1, Math.floor(((y + 1) * h) / 8));
    let s = 0, n = 0;
    for (let yy = y0; yy < Math.min(y1, h); yy++) for (let xx = x0; xx < Math.min(x1, w); xx++) {
      const o = (yy * w + xx) * 4, a = px[o + 3] / 255;
      s += (0.299 * px[o] + 0.587 * px[o + 1] + 0.114 * px[o + 2]) * a; n++; // transparent pixels count as black
    }
    g[y * 9 + x] = n ? s / n : 0;
  }
  const bits: boolean[] = [];
  for (let y = 0; y < 8; y++) for (let x = 0; x < 8; x++) bits.push(g[y * 9 + x + 1] > g[y * 9 + x]);
  return bitsHex(bits);
}

export function audioEnv64(mono: Float32Array | Float64Array | readonly number[]): string | null {
  const n = mono.length;
  if (n < 65 * 8) return null;
  const rms: number[] = [];
  for (let i = 0; i < 65; i++) {
    const a = Math.floor((i * n) / 65), b = Math.floor(((i + 1) * n) / 65);
    let s = 0; for (let j = a; j < b; j++) s += mono[j] * mono[j];
    rms.push(Math.sqrt(s / Math.max(1, b - a)));
  }
  return bitsHex(rms.slice(1).map((v, i) => v > rms[i]));
}

export const modelFactsKey = (f: Pick<GlbFacts, "triangles" | "vertices" | "meshes" | "bounds">) =>
  `t${f.triangles}|v${f.vertices}|m${f.meshes}|b${f.bounds ? f.bounds.map((x) => Math.round(x * 100)).join(",") : "-"}`;

const STRIP = new Set(["name", "id", "label", "title", "displayName", "description"]);
function canonical(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(canonical);
  if (v && typeof v === "object") return Object.fromEntries(Object.keys(v as object).filter((k) => !STRIP.has(k)).sort().map((k) => [k, canonical((v as Record<string, unknown>)[k])]));
  return v;
}
export function motionFactsKey(json: Uint8Array): string | null {
  try { return createHash("sha256").update(JSON.stringify(canonical(JSON.parse(Buffer.from(json).toString("utf8"))))).digest("hex").slice(0, 32); } catch { return null; }
}
// Content-filter hooks for the AUTOMATIC community library (owner decision 2026-10-10: assets made in Cyrus are
// contributed automatically). A new entry is `pending-checks`; runContentFilters() moves it to `published` or
// `held` (or `removed` on a reject), never straight from held to published (only the owner does that).
// The interface is async so a host can plug in an image/audio classifier later; the shipped ruleset is
// deterministic, local and free (filter-rules.json): real-weapon model names, a trademark STUB list, adult terms,
// extremist symbols, mature violence (flag only), plus structural rules (eligibility of the legal class).
// No external service is called. Pure apart from what an injected filter does.
import rules from "./filter-rules.json";
import { libraryEligible } from "../../assets3d/manifest";
import type { CatalogEntry, CatalogStatus } from "./entry";
import { words } from "./vocab";

export type FilterSeverity = "flag" | "hold" | "reject";
export type FilterFlag = { rule: string; severity: FilterSeverity; field: string; match: string; message: string };
export type FilterContext = {
  /** community contributions are checked strictly; Nxeon's own / CC0 pack assets only get flags */
  strict: boolean;
  /** derivedFrom of the source manifest (libraryEligible needs it); [] for packs */
  derivedFrom?: readonly string[];
  provenanceSource?: "user" | "ai" | "library" | "import" | "upload" | "template";
};
export interface ContentFilter {
  readonly id: string;
  check(entry: CatalogEntry, ctx: FilterContext): Promise<FilterFlag[]> | FilterFlag[];
}
export type FilterDecision = { status: CatalogStatus; flags: FilterFlag[]; reason: string | null };

type Rules = typeof rules;
const R: Rules = rules;
const norm = (s: string) => words(s).join(" ");

function fieldsOf(e: CatalogEntry): [string, string][] {
  return [["title", e.title], ["shortDescription", e.shortDescription], ["tags", e.tags.join(" ")], ["freeTags", e.freeTags.join(" ")], ["path", e.provenance.path ?? ""], ["pack", e.provenance.pack ?? ""]];
}
/** whole-word / hyphen-word match on the normalised text ("ak-47" matches "ak 47") */
function find(list: readonly string[], text: string): string | null {
  const t = ` ${norm(text)} `;
  for (const term of list) { const n = norm(term); if (n && t.includes(` ${n} `)) return term; }
  return null;
}

export const wordListFilter = (id: string, list: readonly string[], severity: (e: CatalogEntry, ctx: FilterContext) => FilterSeverity, message: string, fields?: readonly string[]): ContentFilter => ({
  id,
  check(e, ctx) {
    const out: FilterFlag[] = [];
    for (const [field, text] of fieldsOf(e)) {
      if (fields && !fields.includes(field)) continue;
      const m = find(list, text);
      if (m) { out.push({ rule: id, severity: severity(e, ctx), field, match: m, message }); break; }
    }
    return out;
  },
});

/** The first deterministic ruleset. Order does not matter: the strictest severity wins. */
export function defaultFilters(): ContentFilter[] {
  return [
    {
      id: "eligibility",
      check(e, ctx) {
        if (e.licence.tier !== "user-contributed") return [];
