    wordListFilter("extremist", R.extremist, (_e, ctx) => (ctx.strict ? "reject" : "hold"), "extremist symbol terms"),
    wordListFilter("real-weapon", R.realWeapons, (_e, ctx) => (ctx.strict ? "hold" : "flag"), "named after a real firearm model (trademark): owner review", ["title", "shortDescription", "tags", "freeTags", "path"]),
    wordListFilter("trademark", R.trademarks, (e, ctx) => {
