    }, "names a trademark or a game's own content (stub list): owner review"),
    // community assets with gore are HELD for the owner (r26, task: hold queue for trademark / real-weapon / mature); pack assets only flagged
    wordListFilter("mature-violence", R.matureViolence, (_e, ctx) => (ctx.strict ? "hold" : "flag"), "gore / blood (mature violence): owner review for community assets"),
    wordListFilter("drugs", R.drugs, (_e, ctx) => (ctx.strict ? "hold" : "flag"), "drug references"),
  ];
}

const RANK: Record<FilterSeverity, number> = { flag: 0, hold: 1, reject: 2 };

/** pending-checks -> published | held | removed. Entries already held/removed are never auto-published. */
export async function runContentFilters(e: CatalogEntry, ctx: FilterContext, filters: readonly ContentFilter[] = defaultFilters()): Promise<FilterDecision> {
  const flags: FilterFlag[] = [];
  for (const f of filters) {
    try { flags.push(...(await f.check(e, ctx))); }
    catch (err) { flags.push({ rule: f.id, severity: "hold", field: "-", match: "-", message: `filter error: ${String((err as Error)?.message ?? err).slice(0, 80)}` }); } // fail closed
  }
  const worst = flags.reduce<FilterSeverity | null>((w, f) => (w == null || RANK[f.severity] > RANK[w] ? f.severity : w), null);
  if (e.status === "removed") return { status: "removed", flags, reason: e.statusReason };
  if (worst === "reject") return { status: "removed", flags, reason: flags.filter((f) => f.severity === "reject").map((f) => f.message).join("; ").slice(0, 300) };
  if (worst === "hold") return { status: "held", flags, reason: flags.filter((f) => f.severity === "hold").map((f) => `${f.rule}: ${f.match}`).join("; ").slice(0, 300) };
  if (e.status === "held") return { status: "held", flags, reason: e.statusReason ?? "held by the owner" };
  // quality gate: a hard-failed asset (score capped at 20) is never auto-published
  if (e.quality.score <= 20) return { status: "held", flags, reason: "quality hard fail (see quality checks)" };
  return { status: "published", flags, reason: null };
}

/** Write a decision onto an entry: flag ids are `<severity>:<rule>`. */
export function applyDecision(e: CatalogEntry, d: FilterDecision): CatalogEntry {
  return { ...e, status: d.status, statusReason: d.reason, flags: [...new Set(d.flags.map((f) => `${f.severity}:${f.rule}`))].slice(0, 12) };
}

