/** POST /api/cyrus/assets/v1/library/use { projectId, ref, key, expectedHeadId }: add a library texture to the mod. */
export const handleUse = (req: Request, deps: StudioApiDeps) => run(deps, { key: "use", max: 20 }, async ({ viewer }) => {
  const b = await readJson(req);
  const projectId = String(b.projectId ?? ""), ref = String(b.ref ?? ""), key = String(b.key ?? "");
  need(RE.project.test(projectId), "projectId is not valid");
  need(RE.ref.test(ref), "ref is not a library reference");
  need(RE.key.test(key), `The ${ref.startsWith("sound/") ? "sound set" : "texture"} name must be 2-32 lowercase letters, digits and underscores, starting with a letter.`);
  need(b.expectedHeadId === undefined || b.expectedHeadId === null || (typeof b.expectedHeadId === "string" && RE.id.test(b.expectedHeadId)), "expectedHeadId must be a revision id or null");
  const [kind, source, ...rest] = ref.split("/");
  const id = rest.join("/");
  if (kind === "sound") return useSoundLayer(b, { deps, viewer }, source, id);
  if (kind !== "texture") throw new StudioError(400, "not_supported", "Models have no library yet.");
  const plan = await deps.service.planOf(viewer.userId).catch(() => null);
  const g = canBrowse({ signedIn: true, plan }, "texture", source as LibraryAsset["source"]);
  if (!g.ok) throw new StudioError(403, g.code, g.reason, g.needs ? { needs: g.needs } : {});
  const project = await deps.service.store.project(projectId);
  if (!project || project.userId !== viewer.userId) throw new StudioError(404, "not_found", "Project not found.");
  let doc: TextureDoc | null = null;
  let prov: Record<string, unknown> = {};
  if (source === "builtin") {
    const used = await useTextureFromLibrary({ itemId: id, key, namespace: project.namespace }, (k, path) => deps.service.store.reserve(project.id, k, path));
    if (!used.ok) throw new StudioError(400, "library", used.error);
    const item = libraryTexture(id);
    const t = item ? template(item.templateId) : null;
    doc = { ...docFromSpec(used.spec), ...(t?.profile === "tile" ? { tile: { tileable: t.tileable, framed: !!t.framed } } : {}) };
    prov = { library: used.provenance.library, ledger: used.provenance.ledger, identifier: used.identifier };
  } else {
    const m = /^(cp[0-9a-f]{20}):([a-z][a-z0-9_]{1,31})$/.exec(id);
    need(!!m, "ref is not a project asset");
    const src = await deps.service.store.project(m![1]);
    if (!src || src.userId !== viewer.userId) throw new StudioError(404, "not_found", "Asset not found.");
    const row = (await deps.service.store.assets(src.id)).filter((r) => r.kind === "texture" && r.assetKey === m![2]).pop();
    if (!row) throw new StudioError(404, "not_found", "Asset not found.");
    const d = docOfRow(row);
    if (d) doc = { ...d, name: key, ...(d.spec ? { spec: { ...d.spec, name: key } } : {}) };
    else if (row.mime === "image/png" && row.path) {
      const bytes = deps.uploads ? await deps.uploads.get(row.path) : null;
      if (!bytes) throw new StudioError(503, "uploads_off", "Uploaded files aren't available on this server yet.");
      const png = decodePng(bytes, UPLOAD_LIMITS);
      if (!png.ok) throw new StudioError(400, "bad_png", png.error);
      const dd = docFromRaster(key, png.raster);
      if (!dd.ok) throw new StudioError(400, "bad_png", dd.error);
      doc = dd.doc;
    }
    if (!doc) throw new StudioError(400, "not_supported", "This asset has no pixels the studio can use.");
    delete doc.supersedes; delete doc.decision;
    prov = { library: { kind: "texture", from: ref, assetId: row.id } };
    await deps.service.store.reserve(project.id, "model", `item/${key}`);
  }
  const r = await saveTexture(deps.service, { userId: viewer.userId, projectId, key, doc, baseAssetId: null, expectedHeadId: (b.expectedHeadId as string | null) ?? null, origin: "library", provenance: prov });
  return json(201, r);
});

/** POST /api/cyrus/assets/v1/library/upload (multipart: file, projectId, key, profile): a PNG into the project's library. */
export const handleUpload = (req: Request, deps: StudioApiDeps) => run(deps, { key: "upload", max: 6 }, async ({ viewer }) => {
  if (!deps.uploads) throw new StudioError(503, "uploads_off", "Uploads aren't switched on yet.");
  const len = Number(req.headers.get("content-length") ?? 0);
  if (len > UPLOAD_LIMITS.maxBytes + 16 * 1024) throw new StudioError(413, "too_large", `The file is too large; the limit is ${UPLOAD_LIMITS.maxBytes / 1024} KB.`);
  const form = await req.formData().catch(() => null);
  need(!!form, "Send the file as multipart form data.");
  const file = form!.get("file"), projectId = String(form!.get("projectId") ?? ""), key = String(form!.get("key") ?? ""), profile = String(form!.get("profile") ?? "item");
  need(!!file && typeof file === "object" && "arrayBuffer" in file, "Attach a PNG file.");
  need(RE.project.test(projectId), "projectId is not valid");
  need(RE.key.test(key), "The texture name must be 2-32 lowercase letters, digits and underscores, starting with a letter.");
  need(profile === "item" || profile === "tile", "profile must be item or tile");
  const bytes = Buffer.from(await (file as Blob).arrayBuffer());
  const r = await uploadTexture(
    { userId: viewer.userId, projectId, plan: await deps.service.planOf(viewer.userId).catch(() => null), key, name: (file as File).name?.slice(0, 80), bytes, profile: profile as "item" | "tile" },
    { storage: deps.uploads, getProject: (id) => deps.service.store.project(id), recordAsset: (pid, a) => deps.service.store.recordAsset(pid, a) },
  );
  if (!r.ok) return json(r.code === "asset_locked" || r.code === "plan_unknown" ? 403 : r.code === "not_found" ? 404 : 400, { error: r.error, code: r.code, ...(r.quality ? { quality: r.quality } : {}) });
  return json(201, { assetId: r.assetId, quality: r.quality, width: r.width, colours: r.colours, stripped: r.stripped });
});

/** GET /api/cyrus/assets/v1/library/asset/:assetId/png: an uploaded PNG of the viewer's own projects. */
export const handleAssetPng = (_req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "read", max: 240 }, async ({ viewer }) => {
  const { assetId } = params(p, "assetId");
  const row = await deps.service.store.assetById(assetId);
  const proj = row ? await deps.service.store.project(row.projectId) : null;
  if (!row || !proj || proj.userId !== viewer.userId || row.mime !== "image/png" || !row.path) return NOT_FOUND();
  const bytes = deps.uploads ? await deps.uploads.get(row.path) : null;
  if (!bytes) return NOT_FOUND();
  return new Response(new Uint8Array(bytes), { status: 200, headers: { ...H, "content-type": "image/png", "x-content-type-options": "nosniff" } });
});

