// LocalDiskStore: packs on local disk at <root>/p/<sha1>.zip. For dev, tests and a safe fallback.
// Served in dev by app/p/[file]/route.ts (inert unless this store is the selected one).
import { createHash, randomBytes } from "node:crypto";
import { promises as fsp } from "node:fs";
import path from "node:path";
import { packKey, publicPackUrl, SHA1_RE, type PackObject, type PackStore, type PutResult } from "./types";

export class LocalDiskStore implements PackStore {
  readonly kind = "local" as const;
  constructor(readonly root: string, readonly publicBase: string) {
    if (!path.isAbsolute(root)) throw new Error("LocalDiskStore root must be an absolute path");
    publicPackUrl(publicBase, "0".repeat(40)); // validate the base once
  }
  pathFor(sha1: string): string {
    return path.join(this.root, packKey(sha1));
  }
  async put(sha1: string, bytes: Buffer): Promise<PutResult> {
    const key = packKey(sha1);
    const got = createHash("sha1").update(bytes).digest("hex");
    if (got !== sha1) throw new Error(`content sha1 ${got} does not match ${sha1}`);
    const dest = this.pathFor(sha1);
    if (await this.exists(sha1)) return { sha1, key, size: bytes.length, created: false };
    await fsp.mkdir(path.dirname(dest), { recursive: true });
    const tmp = `${dest}.part-${randomBytes(4).toString("hex")}`;
    await fsp.writeFile(tmp, bytes, { flag: "wx" });
    await fsp.rename(tmp, dest);
    return { sha1, key, size: bytes.length, created: true };
  }
  async exists(sha1: string): Promise<boolean> {
    try { return (await fsp.stat(this.pathFor(sha1))).isFile(); } catch { return false; }
  }
  urlFor(sha1: string): string {
    return publicPackUrl(this.publicBase, sha1);
  }
  async read(sha1: string): Promise<Buffer | null> {
    try { return await fsp.readFile(this.pathFor(sha1)); } catch { return null; }
  }
  async delete(sha1: string): Promise<boolean> {
    try { await fsp.unlink(this.pathFor(sha1)); return true; } catch { return false; }
  }
  async list(): Promise<PackObject[]> {
    const dir = path.join(this.root, "p");
    let names: string[];
    try { names = await fsp.readdir(dir); } catch { return []; }
    const out: PackObject[] = [];
    for (const n of names.sort()) {
      const m = /^([0-9a-f]{40})\.zip$/.exec(n);
      if (!m || !SHA1_RE.test(m[1])) continue;
      const st = await fsp.stat(path.join(dir, n));
      if (st.isFile()) out.push({ sha1: m[1], size: st.size, lastModified: st.mtime });
    }
    return out;
  }
}
// Read / write the Pack Loader config on a server through the Mods engine's GuestFs (SSH in production, a local
// fake in tests and SANDBOX). The plugin picks the change up by itself within ~10 s (file watch) or on
// `/nxpacks reload`; no restart. Used by lib/cyrus/assets/deliver.ts (flag-gated; docs "Cyrus asset slice (R1)").
import type { HostGuestFs as GuestFs } from "../host/types";
import { LOADER_CONFIG_PATH, serializeLoaderConfig, validateLoaderConfig, type LoaderConfig } from "./loader-config";
import { cyrusConfig } from "../config";

export const MC_BASE = cyrusConfig().guest.mcBase;
export const loaderConfigGuestPath = (base = MC_BASE) => `${base}/${LOADER_CONFIG_PATH}`;

/** Current config on the server: null when there is none; an error when the file exists but is invalid. */
export async function readLoaderConfig(fs: GuestFs, base = MC_BASE): Promise<{ ok: true; config: LoaderConfig | null } | { ok: false; error: string }> {
  const raw = await fs.readFile(loaderConfigGuestPath(base), 1024 * 1024);
  if (!raw) return { ok: true, config: null };
  let json: unknown;
  try { json = JSON.parse(raw.toString("utf8")); } catch { return { ok: false, error: "packs.json on the server is not valid JSON" }; }
  const v = validateLoaderConfig(json);
  return v.ok ? { ok: true, config: v.config } : { ok: false, error: v.errors.map((e) => e.message).join("; ") };
}

/** Write the config atomically (temp file + rename). Returns false when the bytes on the server are already identical. */
export async function writeLoaderConfig(fs: GuestFs, config: LoaderConfig, base = MC_BASE): Promise<boolean> {
  const v = validateLoaderConfig(config, { requireHttps: true });
  if (!v.ok) throw new Error(`refusing to write an invalid pack config: ${v.errors.map((e) => e.message).join("; ")}`);
  const dest = loaderConfigGuestPath(base);
  const text = Buffer.from(serializeLoaderConfig(config));
  const cur = await fs.readFile(dest, 1024 * 1024);
  if (cur && cur.equals(text)) return false;
  const dir = dest.slice(0, dest.lastIndexOf("/"));
  await fs.mkdirp(dir);
  const tmp = `${dest}.nxeon-part`;
  await fs.writeFile(tmp, text);
  await fs.rename(tmp, dest);
  await fs.chownLike(`${base}/server.properties`, [dir, dest]);
  return true;
}
// Publish a built pack zip: size cap, structural check, sha1, idempotent put, immutable public URL.
import { createHash } from "node:crypto";
import { inspectPackZip } from "./zipcheck";
import type { PackObject, PackStore } from "./types";

export type Published = { ok: true; sha1: string; url: string; bytes: number; created: boolean } | { ok: false; code: "too_large" | "empty" | "bad_zip"; error: string };

export async function publishPack(store: PackStore, zip: Buffer, opts: { maxBytes: number }): Promise<Published> {
  if (!zip.length) return { ok: false, code: "empty", error: "the pack is empty" };
  if (zip.length > opts.maxBytes) return { ok: false, code: "too_large", error: `the pack is ${zip.length} bytes; the limit is ${opts.maxBytes}` };
  const z = inspectPackZip(zip);
  if (!z.ok) return { ok: false, code: "bad_zip", error: z.error };
  const sha1 = createHash("sha1").update(zip).digest("hex");
  const r = await store.put(sha1, zip);
  return { ok: true, sha1, url: store.urlFor(sha1), bytes: zip.length, created: r.created };
}

export type GcPlan = { delete: PackObject[]; keptReferenced: number; keptYoung: number };

/** Pure: unreferenced objects last modified more than `olderThanDays` before `now`. */
export function planPackGc(objects: PackObject[], referenced: ReadonlySet<string>, opts: { now: Date; olderThanDays: number }): GcPlan {
  if (!(opts.olderThanDays >= 1)) throw new Error("olderThanDays must be at least 1 (a fresh upload may not be referenced yet)");
  const cutoff = opts.now.getTime() - opts.olderThanDays * 86400_000;
  const plan: GcPlan = { delete: [], keptReferenced: 0, keptYoung: 0 };
  for (const o of objects) {
    if (referenced.has(o.sha1)) plan.keptReferenced++;
    else if (o.lastModified.getTime() > cutoff) plan.keptYoung++;
    else plan.delete.push(o);
  }
  return plan;
}

/** Retention GC. Dry run by default; `maxDeletes` bounds one pass. `referenced` must be complete (every sha1 any config or revision still points at). */
export async function runPackGc(store: PackStore, referenced: ReadonlySet<string>, opts: { now?: Date; olderThanDays: number; dryRun?: boolean; maxDeletes?: number }) {
  const plan = planPackGc(await store.list(), referenced, { now: opts.now ?? new Date(), olderThanDays: opts.olderThanDays });
  const todo = plan.delete.slice(0, opts.maxDeletes ?? 500);
  const deleted: string[] = [];
  if (opts.dryRun !== false) return { ...plan, deleted, dryRun: true };
  for (const o of todo) if (await store.delete(o.sha1)) deleted.push(o.sha1);
  return { ...plan, deleted, dryRun: false };
}
// Light structural check of a resource-pack zip before it is published: real zip (EOCD + central directory),
// no unsafe entry names, and a pack.mcmeta at the root. Reads only the central directory; never inflates.
export type ZipCheck = { ok: true; entries: string[] } | { ok: false; error: string };

export function inspectPackZip(buf: Buffer, opts: { maxEntries?: number } = {}): ZipCheck {
  const maxEntries = opts.maxEntries ?? 20000;
  if (buf.length < 22 || buf.readUInt32LE(0) !== 0x04034b50) return { ok: false, error: "not a zip file" };
  let eocd = -1;
  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 22 - 0xffff); i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) return { ok: false, error: "zip end-of-central-directory not found" };
  const count = buf.readUInt16LE(eocd + 10);
  const cdSize = buf.readUInt32LE(eocd + 12);
  const cdOff = buf.readUInt32LE(eocd + 16);
  if (count === 0xffff || cdOff === 0xffffffff) return { ok: false, error: "zip64 packs are not accepted" };
  if (count > maxEntries) return { ok: false, error: `too many entries (${count} > ${maxEntries})` };
  if (cdOff + cdSize > eocd) return { ok: false, error: "zip central directory out of range" };
  const entries: string[] = [];
  let p = cdOff;
  for (let n = 0; n < count; n++) {
    if (p + 46 > eocd || buf.readUInt32LE(p) !== 0x02014b50) return { ok: false, error: "corrupt zip central directory" };
    const nameLen = buf.readUInt16LE(p + 28), extra = buf.readUInt16LE(p + 30), comment = buf.readUInt16LE(p + 32);
    const name = buf.subarray(p + 46, p + 46 + nameLen).toString("utf8");
    if (!name || name.startsWith("/") || name.includes("\\") || name.split("/").includes("..") || /[\0]/.test(name)) return { ok: false, error: `unsafe entry name ${JSON.stringify(name)}` };
    entries.push(name);
    p += 46 + nameLen + extra + comment;
  }
  if (!entries.includes("pack.mcmeta")) return { ok: false, error: "pack.mcmeta missing at the zip root" };
  return { ok: true, entries };
}
