// Dev server for LocalDiskStore pack objects: GET /p/<sha1>.zip. Inert (404) unless the selected pack store is the
// local one (CYRUS_PACK_STORE=local, or unset outside production). In production the public base points at object
// storage on an Nxeon domain and this route is never hit.
import { selectPackStore } from "@/lib/cyrus/packhost/config";
import { LocalDiskStore } from "@/lib/cyrus/packhost/local";
import { IMMUTABLE_CACHE_CONTROL, PACK_CONTENT_TYPE, parsePackFile } from "@/lib/cyrus/packhost/types";

export const dynamic = "force-dynamic";

const notFound = () => new Response("Not found", { status: 404, headers: { "Cache-Control": "no-store" } });

async function serve(file: string, head: boolean) {
  const sha1 = parsePackFile(file);
  if (!sha1) return notFound();
  const sel = selectPackStore();
  if (!sel.ok || !(sel.store instanceof LocalDiskStore)) return notFound();
  const bytes = await sel.store.read(sha1);
  if (!bytes) return notFound();
  return new Response(head ? null : new Uint8Array(bytes), {
    headers: {
      "Content-Type": PACK_CONTENT_TYPE,
      "Content-Length": String(bytes.length),
      "Cache-Control": IMMUTABLE_CACHE_CONTROL,
      ETag: `"${sha1}"`,
      "X-Content-Type-Options": "nosniff",
    },
  });
}

export async function GET(_req: Request, { params }: { params: Promise<{ file: string }> }) {
  return serve((await params).file, false);
}
export async function HEAD(_req: Request, { params }: { params: Promise<{ file: string }> }) {
  return serve((await params).file, true);
}
// Cyrus pack hosting (MASTER-PLAN 4.5): content-addressed, immutable resource-pack objects.
// An object is named by the SHA-1 of its bytes (the hash Minecraft checks), at `p/<sha1>.zip`, and never changes.
// Customers only ever see the configured public base domain; the storage provider is never named to them.

export const SHA1_RE = /^[0-9a-f]{40}$/;
/** One year + immutable: the URL is the content hash, so a cached copy can never be stale. */
export const IMMUTABLE_CACHE_CONTROL = "public, max-age=31536000, immutable";
export const PACK_CONTENT_TYPE = "application/zip";
/**
 * Default hard cap per pack: 100 MB. Configurable (CYRUS_PACK_MAX_BYTES). Minecraft's own client-side download
 * limit is UNVERIFIED here (commonly quoted as 250 MB for recent versions; that code is in the client jar, which
 * was not inspected). Keep ours well below it either way: a big pack is a slow join for every player.
 */
export const DEFAULT_MAX_PACK_BYTES = 100 * 1024 * 1024;

export type PackObject = { sha1: string; size: number; lastModified: Date };
export type PutResult = { sha1: string; key: string; size: number; created: boolean };

/** Storage for pack objects. Every method takes the sha1; keys are derived, never caller-chosen. */
export interface PackStore {
  readonly kind: "local" | "s3";
  /** Store bytes under their sha1. Refuses bytes whose sha1 differs. Idempotent: an existing object is left alone. */
  put(sha1: string, bytes: Buffer): Promise<PutResult>;
  exists(sha1: string): Promise<boolean>;
  /** Public URL a Minecraft client downloads from (on the configured base domain). */
  urlFor(sha1: string): string;
  delete(sha1: string): Promise<boolean>;
  list(): Promise<PackObject[]>;
}

export const packKey = (sha1: string): string => {
  if (!SHA1_RE.test(sha1)) throw new Error(`not a sha1: ${sha1}`);
  return `p/${sha1}.zip`;
};

/** `https://packs.example.com` + sha1 -> `https://packs.example.com/p/<sha1>.zip`. Base must be http(s), no query/hash. */
export function publicPackUrl(base: string, sha1: string): string {
  let u: URL;
  try { u = new URL(base); } catch { throw new Error(`pack public base is not a URL: ${base}`); }
  if (u.protocol !== "https:" && u.protocol !== "http:") throw new Error("pack public base must be http(s)");

