export type AuditionDecision = { library: boolean; synth: true; reason: string | null };
/**
 * Who hears what (the server applies the same rule to the preview route): synth layers always play in the browser
 * (pure DSP, original); LIBRARY audio only when the owner cleared the licence (CYRUS_SOUND_LIBRARY_CLEARED=1) AND the
 * plan may use the sound library (Saka and up). Unknown plan = no library audio.
 */
export function auditionDecision(o: { cleared: boolean; plan: unknown }): AuditionDecision {
  if (!o.cleared) return { library: false, synth: true, reason: "Library audition is off until the owner confirms the sound licence. Synth layers play; library layers are drawn from their outline only." };
  const d = canAsset(o.plan, "sound", "create");
  if (!d.ok) return { library: false, synth: true, reason: d.reason };
  return { library: true, synth: true, reason: null };
}

