/** Read-only access to the staged originals. `maxBytes` is checked on the file size BEFORE reading. */
export class StagingSource {
  constructor(readonly root: string) { if (!path.isAbsolute(root)) throw new Error("StagingSource root must be absolute"); }
  async resolve(relPath: string | null): Promise<{ ok: true; path: string; size: number } | Extract<SourceRead, { ok: false }>> {
    if (!relPath || relPath.includes("\0") || path.isAbsolute(relPath) || relPath.split(/[\\/]/).includes("..")) return { ok: false, code: relPath ? "outside_root" : "no_path", error: "the entry has no usable staged path" };
    const p = path.resolve(this.root, relPath);
    let real: string, rootReal: string;
    try { [real, rootReal] = await Promise.all([fsp.realpath(p), fsp.realpath(this.root)]); } catch { return { ok: false, code: "missing", error: "the staged file is missing" }; }
    if (real !== rootReal && !real.startsWith(rootReal + path.sep)) return { ok: false, code: "outside_root", error: "the staged path leaves the staging root" };
    const st = await fsp.stat(real).catch(() => null);
    if (!st?.isFile()) return { ok: false, code: "missing", error: "the staged file is missing" };
    return { ok: true, path: real, size: st.size };
  }
  /** File names (sorted) of a staged FOLDER, path-confined like resolve(); [] when missing or outside the root. */
  async listDir(relPath: string | null): Promise<string[]> {
    if (!relPath || relPath.includes("\0") || path.isAbsolute(relPath) || relPath.split(/[\\/]/).includes("..")) return [];
    try {
      const [real, rootReal] = await Promise.all([fsp.realpath(path.resolve(this.root, relPath)), fsp.realpath(this.root)]);
      if (!real.startsWith(rootReal + path.sep)) return [];
      return (await fsp.readdir(real, { withFileTypes: true })).filter((d) => d.isFile()).map((d) => d.name).sort();
    } catch { return []; }
  }
  async read(relPath: string | null, expectSha: string, maxBytes: number): Promise<SourceRead> {
    const r = await this.resolve(relPath);
    if (!r.ok) return r;
    if (r.size > maxBytes) return { ok: false, code: "too_large", error: `${r.size} bytes is over the ${maxBytes}-byte cap` };
    const bytes = await fsp.readFile(r.path);
    const got = createHash("sha256").update(bytes).digest("hex");
    if (got !== expectSha) return { ok: false, code: "hash_mismatch", error: "the staged file does not match its catalog hash" };
    return { ok: true, bytes, path: r.path };
  }
}

export async function handleUse(req: Request, deps: BrowseDeps): Promise<Response> {
  if (!deps.on()) return NOT_FOUND();
  const v = await deps.viewer().catch(() => null);
  if (!v) return NOT_FOUND();
  const rl = deps.rateLimit(`cyrus:library:use:${v.userId}`, 20, 60_000);
  if (!rl.ok) return json(429, { error: `Too many requests. Wait ${rl.retryAfterSec ?? 30}s.`, code: "rate_limited" });
  let b: Record<string, unknown>;
  try { b = (await req.json()) as Record<string, unknown>; } catch { return json(400, { error: "Send a JSON body.", code: "bad_body" }); }
  const ref = typeof b.ref === "string" && CATALOG_REF_RE.test(b.ref) ? b.ref : null;
  const projectId = typeof b.projectId === "string" && /^cp[0-9a-f]{20}$|^[A-Za-z0-9_-]{4,64}$/.test(b.projectId) ? b.projectId : null;
  const slotId = typeof b.slotId === "string" && /^[a-z][a-z0-9_]{1,31}$/.test(b.slotId) ? b.slotId : null;
  if (!ref || !projectId || !slotId) return json(400, { error: "ref (cat:<sha256>), projectId and slotId (lowercase letters, digits, _) are required.", code: "bad_request" });
  if (!(await deps.ownsProject(v.userId, projectId).catch(() => false))) return NOT_FOUND();
  if (!deps.use) return json(503, { error: "Using library assets in a project is not switched on yet.", code: "use_unavailable" });
  const plan = await deps.planOf(v.userId).catch(() => null);
  const r = await deps.use({ userId: v.userId, ref, projectId, slotId, purpose: typeof b.purpose === "string" ? b.purpose.slice(0, 300) : undefined, plan });
  if (!r.ok) return json(r.code === "asset_locked" || r.code === "tier_locked" ? 403 : r.code === "not_found" || r.code === "not_published" ? 404 : r.code === "bytes_unavailable" ? 503 : 409, { error: r.reason, code: r.code });
  return json(200, r);
}
