  put(a: { projectId: string; slotId: string; kind: AssetSlot["kind"]; bytes: Uint8Array; mime: string; provenance: Record<string, unknown> }): Promise<{ sha256: string; path: string | null }>;
}

export type UseInput = { ref: string; projectId: string; slotId: string; purpose?: string; requirementIds?: string[]; plan: unknown; proprietaryCleared: boolean; game: string | null };
export type UseOk = { ok: true; slot: AssetSlot; use: UseRow; copy: { sha256: string; path: string | null } | null; transform: string[]; reused: boolean; rule: string | null };
export type UseFail = { ok: false; code: Extract<SlotDecision, { ok: false }>["code"] | "bad_request" | "bytes_unavailable"; reason: string };
export type UseDeps = { index: CatalogIndex; store: LibraryStore; uses: LibraryRecords["uses"]; sink: ProjectAssetSink; now: () => Date };

const PROJECT_RE = /^[A-Za-z0-9_-]{4,64}$/;
const slotFor = (e: CatalogEntry, input: UseInput): AssetSlot => ({
  id: input.slotId, kind: gateKindOf(e.kind), purpose: (input.purpose?.trim() || `${e.title} from the asset library`).slice(0, 300),
  source: "library", libraryRef: catalogRef(e.id), requirementIds: input.requirementIds ?? [],
});

export async function useCatalogAsset(input: UseInput, deps: UseDeps): Promise<UseOk | UseFail> {
  if (!CATALOG_REF_RE.test(input.ref)) return { ok: false, code: "bad_ref", reason: "ref must be cat:<sha256>" };
  if (!SLOT_ID_RE.test(input.slotId)) return { ok: false, code: "bad_request", reason: "slot ids are lowercase letters, digits and underscores" };
  if (!PROJECT_RE.test(input.projectId)) return { ok: false, code: "bad_request", reason: "bad project id" };
  const id = input.ref.slice(4);
  const prior = await deps.uses.get(input.projectId, input.slotId);
  const e = await deps.index.get(id);
  if (prior && prior.entryId === id && e) {
    // already in the project: keeping it is never gated
    return { ok: true, slot: slotFor(e, input), use: prior, copy: prior.copySha256 ? { sha256: prior.copySha256, path: null } : null, transform: [], reused: true, rule: null };
  }
  const ctx: ToolContext = { index: deps.index, plan: input.plan, game: input.game, proprietaryCleared: input.proprietaryCleared };
  const d = await resolveLibrarySlot({ id: input.slotId, kind: e ? gateKindOf(e.kind) : "texture", source: "library", libraryRef: input.ref }, ctx);
  if (!d.ok) return d;
  const entry = d.entry;
  const slot = slotFor(entry, input);
  let copy: { sha256: string; path: string | null } | null = null;
  let rule: string | null = null;
  if (entry.licence.tier === "proprietary-nxeon") rule = "proprietary library: rendered and transformed at build time, never copied as the original file";
  else {
    const b = isFolderEntry(entry) ? await deps.store.derivative(entry, "bundle@1") : await deps.store.original(entry);
    if (!b.ok) return { ok: false, code: "bytes_unavailable", reason: `the asset's file is not available (${b.code})` };
    copy = await deps.sink.put({
      projectId: input.projectId, slotId: input.slotId, kind: slot.kind, bytes: b.bytes, mime: b.mime,
      provenance: { libraryRef: slot.libraryRef, licence: { tier: entry.licence.tier, spdx: entry.licence.spdx, attribution: entry.licence.attribution }, legalClass: entry.legalClass, source: entry.provenance.source, pack: entry.provenance.pack },
    });
  }
  const use = await deps.uses.upsert({ entryId: entry.id, projectId: input.projectId, slotId: input.slotId, kind: entry.kind, copySha256: copy?.sha256 ?? null, upstream: entry.status }, deps.now());
  return { ok: true, slot, use, copy, transform: d.transform, reused: false, rule };
}

export type BuildSlotDecision =
  | { ok: true; from: "project-copy"; copySha256: string; upstream: UseRow["upstream"]; notice: string | null }
  | { ok: true; from: "library"; entry: CatalogEntry; transform: string[]; notice: string | null }
  | Extract<SlotDecision, { ok: false }>
  | { ok: false; code: "upstream_unavailable"; reason: string };

export async function resolveSlotForBuild(slot: Pick<AssetSlot, "id" | "kind" | "source"> & { libraryRef?: string }, ctx: ToolContext & { projectId: string; uses: LibraryRecords["uses"] }): Promise<BuildSlotDecision> {
  if (slot.source === "library" && slot.libraryRef && CATALOG_REF_RE.test(slot.libraryRef)) {
    const use = await ctx.uses.get(ctx.projectId, slot.id);
    if (use && catalogRef(use.entryId) === slot.libraryRef) {
      const notice = use.upstream === "removed" ? "this library asset was removed from the library; the mod keeps using its own copy" : null;
      if (use.copySha256) return { ok: true, from: "project-copy", copySha256: use.copySha256, upstream: use.upstream, notice };
      // a library render (proprietary sounds): not plan-gated (rebuild), but the asset must still be servable
      const e = await ctx.index.get(use.entryId);
      if (!e || e.status !== "published") return { ok: false, code: "upstream_unavailable", reason: `${slot.libraryRef} is no longer in the library and the project holds no copy (library render)` };
      if (e.licence.tier === "proprietary-nxeon" && !ctx.proprietaryCleared) return { ok: false, code: "upstream_unavailable", reason: "the Nxeon sound library is not cleared for builds" };
      return { ok: true, from: "library", entry: e, transform: e.games[ctx.game ?? ""]?.transform ?? [], notice };
    }
  }
  const d = await resolveLibrarySlot(slot, ctx);
  return d.ok ? { ok: true, from: "library", entry: d.entry, transform: d.transform, notice: null } : d;
}

/** In-memory sink (tests / single box): sha256 of the bytes, no path. */
export function createMemoryProjectSink(): ProjectAssetSink & { items: Map<string, { bytes: Uint8Array; mime: string; provenance: Record<string, unknown> }> } {
  const items = new Map<string, { bytes: Uint8Array; mime: string; provenance: Record<string, unknown> }>();
  return {
    items,
    async put(a) {
      const { createHash } = await import("node:crypto");
      const sha256 = createHash("sha256").update(a.bytes).digest("hex");
      items.set(`${a.projectId}|${a.slotId}|${sha256}`, { bytes: Uint8Array.from(a.bytes), mime: a.mime, provenance: a.provenance });
      return { sha256, path: null };
    },
  };
}
